// Original GCSE cutaway layout. Coordinates are shared by SVG and the 3D mesh.
export const heartOutline=[['M',228,153],['C',187,120,140,140,125,194],['C',102,253,123,332,184,386],['C',222,420,270,450,315,472],['C',338,476,365,428,394,383],['C',438,320,451,250,423,198],['C',405,162,375,141,345,148],['L',292,160],['Z']];
export function heartChambers(thick=true){return [
 {id:'ra',name:'Right atrium',anchor:[180,218],commands:[['M',153,190],['C',167,169,205,173,223,194],['C',239,212,235,243,216,257],['C',191,267,154,252,146,232],['C',139,215,144,198,153,190],['Z']]},
 {id:'rv',name:'Right ventricle',anchor:[204,333],commands:[['M',215,279],['C',190,266,155,288,169,326],['C',189,362,251,401,291,420],['C',257,374,250,334,258,299],['C',247,286,232,281,215,279],['Z']]},
 {id:'la',name:'Left atrium',anchor:[352,216],commands:[['M',324,186],['C',344,166,379,179,392,204],['C',404,226,384,250,362,258],['C',341,263,313,248,310,225],['C',307,208,313,196,324,186],['Z']]},
 {id:'lv',name:'Left ventricle',anchor:[335,343],commands:thick?[['M',316,281],['C',346,265,380,288,373,330],['C',365,368,345,399,329,423],['C',313,385,296,340,303,301],['C',305,291,310,286,316,281],['Z']]:[['M',311,277],['C',371,252,408,284,399,336],['C',386,387,352,426,330,443],['C',307,392,286,339,299,294],['Z']]}
 ];}
export const heartVessels=[
 {id:'aorta',name:'Aorta',colour:0xc96d60,r:16,points:[[318,305,-.02],[279,214,-.1],[279,130,-.3],[294,70,-.3],[335,58,-.35],[374,83,-.35],[386,135,-.4]]},
 {id:'cava',name:'Vena cava',colour:0x7c9da8,r:14,points:[[157,58,-.15],[154,116,-.15],[161,184,-.1],[173,199,-.08]]},
 {id:'inferior-cava',name:'Vena cava',colour:0x7c9da8,r:12,points:[[113,368,-.1],[115,304,-.1],[137,253,-.1],[155,233,-.06]]},
 {id:'pv',name:'Pulmonary veins',colour:0xd68775,r:10,points:[[469,167,-.1],[431,175,-.1],[396,197,-.06],[377,210,-.02]]},
 {id:'pv2',name:'Pulmonary veins',colour:0xd68775,r:9,points:[[472,202,-.1],[437,206,-.1],[407,219,-.06],[384,229,-.02]]},
 {id:'pa',name:'Pulmonary artery',colour:0x7c9da8,r:14,points:[[239,301,.15],[240,238,.18],[242,173,.2],[254,131,.22],[309,118,.2],[365,112,.16],[438,111,.08]]}
];
export const chamberRoles={ra:'Receives blood returning from the body',rv:'Pumps blood to the lungs',la:'Receives blood returning from the lungs',lv:'Pumps blood to the body at higher pressure'};
export const pathData=commands=>commands.map(c=>c.join(' ')).join(' ');
export function anatomyPath(T,commands,hole=false){const shape=hole?new T.Path():new T.Shape(),xy=(x,y)=>[(x-280)/90,(275-y)/90];for(let [op,...v]of commands){if(op==='M')shape.moveTo(...xy(...v));else if(op==='L')shape.lineTo(...xy(...v));else if(op==='C')shape.bezierCurveTo(...xy(v[0],v[1]),...xy(v[2],v[3]),...xy(v[4],v[5]));else if(op==='Q')shape.quadraticCurveTo(...xy(v[0],v[1]),...xy(v[2],v[3]));else shape.closePath();}return shape;}
export function buildHeart(group,T,w={}){
 const material=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.34,metalness:.02,...extra}),chambers=heartChambers(w.thick!==false),body=anatomyPath(T,heartOutline);
 for(let c of chambers)body.holes.push(anatomyPath(T,c.commands,true));
 const muscle=new T.Mesh(new T.ExtrudeGeometry(body,{depth:.6,bevelEnabled:true,bevelSize:.025,bevelThickness:.035,bevelSegments:3,curveSegments:36}),[material(0xce8c7d),material(0x9f5c55)]);muscle.position.z=-.1;muscle.name='myocardium';group.add(muscle);
 for(let c of chambers){const cavity=new T.Mesh(new T.ExtrudeGeometry(anatomyPath(T,c.commands),{depth:.12,bevelEnabled:true,bevelSize:.04,bevelThickness:.035,bevelSegments:3,curveSegments:32}),material(c.id.startsWith('r')?0x678b98:0xb55750));cavity.position.z=-.18;cavity.name=c.id;group.add(cavity);if(w.selected===c.id){const pts=anatomyPath(T,c.commands).getPoints(90).map(p=>new T.Vector3(p.x,p.y,.58));const rim=new T.LineLoop(new T.BufferGeometry().setFromPoints(pts),new T.LineBasicMaterial({color:0xfff5d7}));rim.name='selected-'+c.id;group.add(rim);}}
 for(let v of heartVessels){const pts=v.points.map(([x,y,z])=>new T.Vector3((x-280)/90,(275-y)/90,z+.25)),curve=new T.CatmullRomCurve3(pts),tube=new T.Mesh(new T.TubeGeometry(curve,64,v.r/90,24,false),material(v.colour));tube.name=v.id;group.add(tube);const last=pts.at(-1),opening=new T.Mesh(new T.CircleGeometry(v.r/90*.75,32),material(v.colour===0x7c9da8?0x304d5c:0x853a39,{side:T.DoubleSide}));opening.position.copy(last);opening.quaternion.setFromUnitVectors(new T.Vector3(0,0,1),curve.getTangent(1));group.add(opening);}
 // Atrioventricular flaps and supporting cords. No named-valve recall is added.
 for(let [cx,cy,width]of [[210,269,38],[340,270,38]]){for(let sign of[-1,1]){const s=new T.Shape();s.moveTo((cx+sign*width/2-280)/90,(275-cy)/90);s.lineTo((cx-280)/90,(275-cy-12)/90);s.quadraticCurveTo((cx+sign*8-280)/90,(275-cy-1)/90,(cx+sign*width/2-280)/90,(275-cy)/90);const flap=new T.Mesh(new T.ExtrudeGeometry(s,{depth:.025,bevelEnabled:false}),material(0xf2d8b0,{side:T.DoubleSide}));flap.position.z=.57;flap.name='valve';group.add(flap);const cord=new T.Line(new T.BufferGeometry().setFromPoints([new T.Vector3((cx+sign*8-280)/90,(275-cy-10)/90,.59),new T.Vector3((cx+sign*12-280)/90,(275-cy-48)/90,.3)]),new T.LineBasicMaterial({color:0xe9c8ad}));group.add(cord);}}
}
let serial=0;
export function anatomicalHeartFigure(w={}){
 const id='heartCut'+(++serial),selected=w.selected,paths=heartChambers(w.thick!==false),vessels=heartVessels.map(v=>{const pts=v.points;let d=`M${pts[0][0]} ${pts[0][1]}`;for(let i=1;i<pts.length-1;i++)d+=` Q${pts[i][0]} ${pts[i][1]} ${(pts[i][0]+pts[i+1][0])/2} ${(pts[i][1]+pts[i+1][1])/2}`;d+=` T${pts.at(-1)[0]} ${pts.at(-1)[1]}`;return `<path d="${d}" stroke="#${v.colour.toString(16)}" stroke-width="${v.r*2}" fill="none" stroke-linejoin="round"/><path d="${d}" stroke="#f5dfd3" stroke-opacity=".18" stroke-width="${v.r*.6}" fill="none"/>`;}).join('');
 const label=(x,y,a,b,anchor='middle')=>`<text x="${x}" y="${y}" text-anchor="${anchor}" fill="#f8f6f2" font-size="17" font-family="inherit">${a}${b?`<tspan x="${x}" dy="19">${b}</tspan>`:''}</text>`;
 return `<svg class="shell-diagram heart-cutaway" viewBox="0 0 540 520" role="img" aria-label="Labelled cutaway heart: four connected chambers, vena cava, pulmonary artery, pulmonary veins, aorta, valves and septum; organ right appears on viewer left"><defs><linearGradient id="${id}wall" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#e9b3a0"/><stop offset=".55" stop-color="#c77e72"/><stop offset="1" stop-color="#a85e58"/></linearGradient><linearGradient id="${id}right"><stop stop-color="#7597a5"/><stop offset="1" stop-color="#365867"/></linearGradient><linearGradient id="${id}left"><stop stop-color="#ce7b6d"/><stop offset="1" stop-color="#883e41"/></linearGradient><marker id="${id}arrow" markerWidth="5" markerHeight="5" refX="3" refY="2.5" orient="auto"><path d="M0 0L4 2.5L0 5Z" fill="#fff1d8"/></marker></defs>${vessels}<path d="${pathData(heartOutline)}" fill="url(#${id}wall)" stroke="#efc5b4" stroke-width="2"/>${paths.map(c=>`<path d="${pathData(c.commands)}" fill="url(#${id}${c.id.startsWith('r')?'right':'left'})" stroke="${selected===c.id?'#fff5d7':'#edd0be'}" stroke-width="${selected===c.id?5:2}"/>`).join('')}
 <path d="M318 305Q280 238 279 162" fill="none" stroke="#c96d60" stroke-width="24"/><path d="M239 301Q239 212 244 167Q250 132 273 125" fill="none" stroke="#7c9da8" stroke-width="27"/>
 <path d="M215 260L207 283L190 266M323 268L336 286L356 264" fill="#f3dcb9" stroke="#f8ecd5" stroke-width="2"/><path d="M207 282L211 313M336 285L337 317" stroke="#f2d8b0" stroke-width="2"/>
 <path d="M169 198L185 238M212 300Q214 342 249 369M360 201L350 238M330 380Q317 342 324 304" fill="none" stroke="#fff1d8" stroke-width="2.5" marker-end="url(#${id}arrow)" opacity=".9"/>
 <g fill="none" stroke="#c9d4d7" stroke-width="1.4"><path d="M179 215L101 214L88 214"/><path d="M206 337L106 353L88 353"/><path d="M352 215L438 238L451 238"/><path d="M341 348L437 379L450 379"/><path d="M281 352L272 479"/><path d="M155 83L109 83"/><path d="M341 59L374 29"/></g>
 ${label(82,208,'Right','atrium','end')}${label(82,347,'Right','ventricle','end')}${label(454,232,'Left','atrium','start')}${label(454,373,'Left','ventricle','start')}${label(265,503,'Septum')}${label(101,72,'Vena','cava','end')}${label(382,27,'Aorta',null,'start')}${label(437,77,'Pulmonary','artery')}${label(487,152,'Pulmonary','veins')}
 </svg><div class="heart-map-key"><span><i class="heart-key-right"></i>To lungs</span><span><i class="heart-key-left"></i>To body</span><span><i class="heart-key-valve"></i>Valve flaps</span></div>`;
}
